#include <iostream>
#include <vector>
#include <cmath>

using namespace std;

double getAn(const vector<int>& p1, const vector<int>& p2, const vector<int>& p3) {
    double dot = 0, aLen = 0, bLen = 0;
    for (int i = 0; i < p1.size(); ++i) {
        double v1 = p2[i] - p1[i];
        double v2 = p3[i] - p1[i];
        dot += v1 * v2;
        aLen += v1 * v1;
        bLen += v2 * v2;
    }
    return 180.0 * acos(dot / sqrt(aLen * bLen)) / M_PI;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    if (n > 20) {
        cout << 0 << "\n";
    } else {
        vector<vector<int>> p(n, vector<int>(5));
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < 5; ++j) {
                cin >> p[i][j];
            }
        }

        vector<int> good;

        for (int i = 0; i < n; ++i) {
            bool is_good = true;
            for (int j = 0; j < n && is_good; ++j) {
                if (i != j) {
                    for (int k = j + 1; k < n; ++k) {
                        if (i != k) {
                            if (getAn(p[i], p[j], p[k]) < 90.0) {
                                is_good = false;
                                break;
                            }
                        }
                    }
                }
            }
            if (is_good) {
                good.push_back(i + 1);
            }
        }

        cout << (int)good.size() << "\n";
        for (auto& idx : good) {
            cout << idx << "\n";
        }
    }
    return 0;
}
